-- JLPT: 43 anh bai doc cuoi da upload va xac minh, gan vao 80 cau.
-- MySQL 8. Chon dung DB cua kotsukotsu.id.vn truoc khi chay.
-- Chay toan bo file trong mot ket noi. Co the chay lai.
-- Chi cap nhat jlpt_question.image_url; giu nguyen diem, dap an, audio va noi dung.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP TEMPORARY TABLE IF EXISTS jlpt_reading_image_plan;
CREATE TEMPORARY TABLE jlpt_reading_image_plan (
 question_id BIGINT UNSIGNED PRIMARY KEY,
 exam_code VARCHAR(50) NOT NULL,
 part_code VARCHAR(30) NOT NULL,
 mondai_number INT NOT NULL,
 question_number INT NOT NULL,
 question_text TEXT NOT NULL,
 old_image VARCHAR(1000) NULL,
 new_image VARCHAR(1000) NOT NULL
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

START TRANSACTION;
UPDATE jlpt_question q
JOIN jlpt_reading_image_plan a ON a.question_id=q.id AND a.question_number=q.question_number
JOIN jlpt_mondai m ON m.id=q.mondai_id AND m.mondai_number=a.mondai_number
JOIN jlpt_part p ON p.id=m.part_id AND p.part_code=a.part_code COLLATE utf8mb4_unicode_ci
JOIN jlpt_exam e ON e.id=p.exam_id AND e.exam_code=a.exam_code COLLATE utf8mb4_unicode_ci
SET q.image_url=a.new_image
WHERE BINARY q.question_text=BINARY a.question_text
  AND (BINARY q.image_url <=> BINARY a.old_image);
SET @jlpt_reading_image_rows_updated=ROW_COUNT();

SELECT DATABASE() AS target_schema, COUNT(*) AS planned_reading_questions,
 @jlpt_reading_image_rows_updated AS updated_this_run,
 SUM(CASE WHEN e.id IS NOT NULL AND BINARY q.question_text=BINARY a.question_text
      AND BINARY q.image_url=BINARY a.new_image THEN 1 ELSE 0 END) AS linked_after_update
FROM jlpt_reading_image_plan a
LEFT JOIN jlpt_question q ON q.id=a.question_id AND q.question_number=a.question_number
LEFT JOIN jlpt_mondai m ON m.id=q.mondai_id AND m.mondai_number=a.mondai_number
LEFT JOIN jlpt_part p ON p.id=m.part_id AND p.part_code=a.part_code COLLATE utf8mb4_unicode_ci
LEFT JOIN jlpt_exam e ON e.id=p.exam_id AND e.exam_code=a.exam_code COLLATE utf8mb4_unicode_ci;

SELECT a.exam_code,a.mondai_number,a.question_number,a.question_id
FROM jlpt_reading_image_plan a
LEFT JOIN jlpt_question q ON q.id=a.question_id AND q.question_number=a.question_number
LEFT JOIN jlpt_mondai m ON m.id=q.mondai_id AND m.mondai_number=a.mondai_number
LEFT JOIN jlpt_part p ON p.id=m.part_id AND p.part_code=a.part_code COLLATE utf8mb4_unicode_ci
LEFT JOIN jlpt_exam e ON e.id=p.exam_id AND e.exam_code=a.exam_code COLLATE utf8mb4_unicode_ci
WHERE e.id IS NULL OR NOT (BINARY q.question_text <=> BINARY a.question_text)
 OR NOT (BINARY q.image_url <=> BINARY a.new_image);
COMMIT;
DROP TEMPORARY TABLE jlpt_reading_image_plan;
